        await SeedSessionAsync(factory, rawToken, "mailfail@staff.example.edu", UserRole.Supervisor, ct);
        var email = Substitute.For<IRegistrationEmailService>();
        email.SendRegistrationSuccessEmailAsync("mailfail@staff.example.edu", "Mail", ct)
            .Returns(_ => Task.FromException(new InvalidOperationException("mail unavailable")));
        var access = Substitute.For<IAccessTokenService>();
        access.Generate(Arg.Any<User>()).Returns("access");
        var hasher = Substitute.For<IPasswordHasher>();
        hasher.Hash(Arg.Any<string>()).Returns("hash");
        var sut = CreateSut(factory, PassingPasswordPolicy(), hasher, access, email);

        var result = await sut.CompleteRegistrationAsync(new RegisterCompleteRequest
        {
            RegistrationToken = rawToken,
            Fname = "Mail",
            Lname = "Failure",
            Password = "StrongPassword!1"
        }, ct);

        Assert.Equal("access", result.AccessToken);
        await using var db = factory.CreateDbContext();
        Assert.Single(await db.Users.ToListAsync(ct));
    }

    private static RegistrationService CreateSut(
        IDbContextFactory<AuthDbContext> factory,
        IPasswordPolicyValidator policy,
        IPasswordHasher hasher,
        IAccessTokenService? access = null,
        IRegistrationEmailService? email = null) =>
        new(
            factory,
            Options(),
            policy,
            new JwtOptions("issuer", "audience", new string('x', 64), 15, 30),
            hasher,
            access ?? Substitute.For<IAccessTokenService>(),
            email ?? Substitute.For<IRegistrationEmailService>(),
            NullLogger<RegistrationService>.Instance);

    private static IPasswordPolicyValidator PassingPasswordPolicy()
    {
        var policy = Substitute.For<IPasswordPolicyValidator>();
        policy.Validate(Arg.Any<string>(), Arg.Any<string>()).Returns(Array.Empty<ApiFieldError>());
        return policy;
    }

    private static RegistrationOptions Options() => new(
        true,
        "student.example.edu",
        "staff.example.edu",
        true,
        "^IT[0-9]{8}$",
        true,
        true,
        50,
        50,
        200,
        20,
        300,
        600);

    private static async Task SeedUserAsync(
        SqliteAuthDbContextFactory factory,
        string email,
        UserRole role,
        string? registrationNumber,
        CancellationToken ct)
    {
        await using var db = factory.CreateDbContext();
        db.Users.Add(new User
        {
            Id = Guid.NewGuid(),
            Email = email.ToLowerInvariant(),
            FirstName = "Existing",
            LastName = "User",
            PasswordHash = "hash",
            Role = role,
            RegistrationNumber = registrationNumber,
            CreatedAt = DateTime.UtcNow
        });
        await db.SaveChangesAsync(ct);
    }

    private static async Task SeedSessionAsync(
        SqliteAuthDbContextFactory factory,
        string rawToken,
        string email,
        UserRole role,
        CancellationToken ct)
    {
        await using var db = factory.CreateDbContext();
        db.RegistrationSessions.Add(new RegistrationSession
        {
            Id = Guid.NewGuid(),
            TokenHash = Sha256Base64(rawToken),
            Email = email,
            Role = role,
            CreatedAt = DateTime.UtcNow.AddMinutes(-1),
            ExpiresAt = DateTime.UtcNow.AddMinutes(10)
        });
        await db.SaveChangesAsync(ct);
    }

    private static string Sha256Base64(string raw) =>
        Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(raw)));

    private sealed class SqliteAuthDbContextFactory : IDbContextFactory<AuthDbContext>, IAsyncDisposable
    {
        private readonly SqliteConnection _connection;
        private readonly DbContextOptions<AuthDbContext> _options;

        private SqliteAuthDbContextFactory(SqliteConnection connection)
        {
            _connection = connection;
            _options = new DbContextOptionsBuilder<AuthDbContext>().UseSqlite(connection).Options;
        }

        public static async Task<SqliteAuthDbContextFactory> CreateAsync(CancellationToken ct)
        {
            var connection = new SqliteConnection("Data Source=:memory:");
            await connection.OpenAsync(ct);
            var factory = new SqliteAuthDbContextFactory(connection);
            await using var db = factory.CreateDbContext();
            await db.Database.EnsureCreatedAsync(ct);
            return factory;
        }

        public AuthDbContext CreateDbContext() => new(_options);
        public Task<AuthDbContext> CreateDbContextAsync(CancellationToken cancellationToken = default) => Task.FromResult(CreateDbContext());
        public ValueTask DisposeAsync() => _connection.DisposeAsync();
    }
}

using Microsoft.EntityFrameworkCore;
using NSubstitute;
using ResearchTrack.AuthService.Configuration;
using ResearchTrack.AuthService.Contracts;
using ResearchTrack.AuthService.Domain;
using ResearchTrack.AuthService.Features.Authentication;
using ResearchTrack.AuthService.Infrastructure.Security;
using ResearchTrack.AuthService.Infrastructure.Tokens;
using ResearchTrack.AuthService.Persistence;
using ResearchTrack.BuildingBlocks.Api.Exceptions;

namespace ResearchTrack.AuthService.MutationTests.Services;

public sealed class UserAuthenticationServiceMockTests
{
    [Fact]
    public async Task LoginAsync_ValidCredentials_VerifiesPasswordGeneratesTokenAndPersistsRefreshToken()
    {
        var factory = new TestAuthDbContextFactory();
        var user = await SeedUserAsync(factory, "student@example.com", "stored-hash");
        var hasher = Substitute.For<IPasswordHasher>();
        hasher.Hash(Arg.Any<string>()).Returns("dummy-hash");
        hasher.Verify("Correct#123", "stored-hash").Returns(true);
        var tokenService = Substitute.For<IAccessTokenService>();
        tokenService.Generate(Arg.Any<User>()).Returns("access-token");
        var sut = CreateSut(factory, hasher, tokenService);

        var result = await sut.LoginAsync(
            new LoginRequest { Email = "  STUDENT@EXAMPLE.COM ", Password = "Correct#123" },
            CancellationToken.None);

        Assert.Equal("access-token", result.AccessToken);
        Assert.Equal(user.Id, result.Response.User.Id);
        Assert.False(string.IsNullOrWhiteSpace(result.RefreshToken));
        hasher.Received(1).Verify("Correct#123", "stored-hash");
        tokenService.Received(1).Generate(Arg.Is<User>(x => x.Id == user.Id));
        await using var verify = factory.CreateDbContext();
        var refresh = Assert.Single(verify.RefreshTokens);
        Assert.Equal(user.Id, refresh.UserId);
        Assert.NotEqual(result.RefreshToken, refresh.TokenHash);
    }

    [Fact]
    public async Task LoginAsync_WrongPassword_DoesNotGenerateTokenOrPersistRefreshToken()
    {
        var factory = new TestAuthDbContextFactory();
        await SeedUserAsync(factory, "student@example.com", "stored-hash");
        var hasher = Substitute.For<IPasswordHasher>();
        hasher.Hash(Arg.Any<string>()).Returns("dummy-hash");
        hasher.Verify("wrong", "stored-hash").Returns(false);
        var tokenService = Substitute.For<IAccessTokenService>();
        var sut = CreateSut(factory, hasher, tokenService);

        await Assert.ThrowsAsync<ApiException>(() => sut.LoginAsync(
            new LoginRequest { Email = "student@example.com", Password = "wrong" },
            CancellationToken.None));

        tokenService.DidNotReceive().Generate(Arg.Any<User>());
        await using var verify = factory.CreateDbContext();
        Assert.Empty(verify.RefreshTokens);
    }

    [Fact]
    public async Task LoginAsync_UnknownUser_ExecutesTimingGuardAndDoesNotGenerateToken()
    {
        var factory = new TestAuthDbContextFactory();
        var hasher = Substitute.For<IPasswordHasher>();
        hasher.Hash(Arg.Any<string>()).Returns("dummy-hash");
        hasher.Verify("Secret#123", "dummy-hash").Returns(false);
        var tokenService = Substitute.For<IAccessTokenService>();
        var sut = CreateSut(factory, hasher, tokenService);

        await Assert.ThrowsAsync<ApiException>(() => sut.LoginAsync(
            new LoginRequest { Email = "missing@example.com", Password = "Secret#123" },
            CancellationToken.None));

        hasher.Received(1).Verify("Secret#123", "dummy-hash");
        tokenService.DidNotReceive().Generate(Arg.Any<User>());
    }

    private static UserAuthenticationService CreateSut(
        IDbContextFactory<AuthDbContext> factory,
        IPasswordHasher hasher,
        IAccessTokenService tokenService) =>
        new(factory, hasher, new InvalidPasswordTimingGuard(hasher), tokenService,
            new JwtOptions("issuer", "audience", new string('k', 64), 15, 7));

    private static async Task<User> SeedUserAsync(TestAuthDbContextFactory factory, string email, string passwordHash)
    {
        var user = new User
        {
            Id = Guid.NewGuid(), Email = email, FirstName = "Sam", LastName = "Student",
            PasswordHash = passwordHash, Role = UserRole.Student, CreatedAt = DateTime.UtcNow
        };
        await using var db = factory.CreateDbContext();
        db.Users.Add(user);
        await db.SaveChangesAsync(CancellationToken.None);
        return user;
    }

    private sealed class TestAuthDbContextFactory : IDbContextFactory<AuthDbContext>
    {
        private readonly DbContextOptions<AuthDbContext> _options = new DbContextOptionsBuilder<AuthDbContext>()
            .UseInMemoryDatabase($"auth-mock-tests-{Guid.NewGuid():N}")
            .Options;
        public AuthDbContext CreateDbContext() => new(_options);
        public Task<AuthDbContext> CreateDbContextAsync(CancellationToken cancellationToken = default) => Task.FromResult(CreateDbContext());
    }
}

using Microsoft.EntityFrameworkCore;
using ResearchTrack.AuthService.Domain;
using ResearchTrack.AuthService.Features.Users;
using ResearchTrack.AuthService.Persistence;

namespace ResearchTrack.AuthService.MutationTests.Services;

public sealed class UserDirectoryServiceCoverageTests
{
    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("  ")]
    [InlineData("ab")]
    public async Task SearchStudentsAsync_ShortOrBlankQuery_ReturnsEmptyWithoutDatabase(string? query)
    {
        var sut = new UserDirectoryService(new ThrowingFactory());

        var result = await sut.SearchStudentsAsync(query, CancellationToken.None);

        Assert.Empty(result);
    }

    [Fact]
    public async Task SearchStudentsAsync_MatchesStudentFields_ExcludesSupervisors_AndOrdersByName()
    {
        var factory = new TestAuthDbContextFactory();
        await SeedAsync(factory,
            Student("sam.one@example.edu", "Sam", "One", "IT1001"),
            Student("alex.sam@example.edu", "Alex", "Beta", "IT2002"),
            Supervisor("sam.supervisor@example.edu", "Sam", "Supervisor"));
        var sut = new UserDirectoryService(factory);

        var result = await sut.SearchStudentsAsync(" sam ", CancellationToken.None);

        Assert.Equal(2, result.Count);
        Assert.Equal("Alex", result[0].FirstName);
        Assert.Equal("Sam", result[1].FirstName);
        Assert.All(result, item => Assert.Equal("STUDENT", item.Role));
    }

    [Fact]
    public async Task SearchStudentsAsync_RegistrationNumberMatch_ReturnsStudent()
    {
        var factory = new TestAuthDbContextFactory();
        var student = Student("student@example.edu", "Nina", "Perera", "IT998877");
        await SeedAsync(factory, student);
        var sut = new UserDirectoryService(factory);

        var result = await sut.SearchStudentsAsync("998877", CancellationToken.None);

        var item = Assert.Single(result);
        Assert.Equal(student.Id, item.Id);
        Assert.Equal("IT998877", item.RegistrationNumber);
    }

    [Fact]
    public async Task ResolveStudentsAsync_EmptyInput_ReturnsEmptyWithoutDatabase()
    {
        var sut = new UserDirectoryService(new ThrowingFactory());

        var result = await sut.ResolveStudentsAsync([], CancellationToken.None);

        Assert.Empty(result);
    }

    [Fact]
    public async Task ResolveStudentsAsync_DeduplicatesIds_AndExcludesSupervisor()
    {
        var factory = new TestAuthDbContextFactory();
        var student = Student("student@example.edu", "Asha", "Silva", "IT123");
        var supervisor = Supervisor("supervisor@example.edu", "Zed", "Supervisor");
        await SeedAsync(factory, student, supervisor);
        var sut = new UserDirectoryService(factory);

        var result = await sut.ResolveStudentsAsync(
            [student.Id, student.Id, supervisor.Id],
            CancellationToken.None);

        var item = Assert.Single(result);
        Assert.Equal(student.Id, item.Id);
        Assert.Equal("STUDENT", item.Role);
    }

    [Fact]
    public async Task GetUserAsync_ReturnsMappedUser_AndNullForMissingUser()
    {
        var factory = new TestAuthDbContextFactory();
        var supervisor = Supervisor("supervisor@example.edu", "Ada", "Lovelace");
        await SeedAsync(factory, supervisor);
        var sut = new UserDirectoryService(factory);

        var found = await sut.GetUserAsync(supervisor.Id, CancellationToken.None);
        var missing = await sut.GetUserAsync(Guid.NewGuid(), CancellationToken.None);

        Assert.NotNull(found);
        Assert.Equal("SUPERVISOR", found!.Role);
        Assert.Equal("Ada", found.FirstName);
        Assert.Null(missing);
    }

    private static User Student(string email, string first, string last, string registration) => new()
    {
        Id = Guid.NewGuid(),
        Email = email,
        FirstName = first,
        LastName = last,
        PasswordHash = "hash",
        Role = UserRole.Student,
        RegistrationNumber = registration,
        CreatedAt = DateTime.UtcNow
    };

    private static User Supervisor(string email, string first, string last) => new()
    {
        Id = Guid.NewGuid(),
        Email = email,
        FirstName = first,
        LastName = last,
        PasswordHash = "hash",
        Role = UserRole.Supervisor,
        CreatedAt = DateTime.UtcNow
    };

    private static async Task SeedAsync(TestAuthDbContextFactory factory, params User[] users)
    {
        await using var db = factory.CreateDbContext();
        db.Users.AddRange(users);
        await db.SaveChangesAsync(CancellationToken.None);
    }

    private sealed class TestAuthDbContextFactory : IDbContextFactory<AuthDbContext>
    {
        private readonly DbContextOptions<AuthDbContext> _options =
            new DbContextOptionsBuilder<AuthDbContext>()
                .UseInMemoryDatabase($"auth-directory-{Guid.NewGuid():N}")
                .Options;

        public AuthDbContext CreateDbContext() => new(_options);

        public Task<AuthDbContext> CreateDbContextAsync(CancellationToken cancellationToken = default) =>
            Task.FromResult(CreateDbContext());
    }

    private sealed class ThrowingFactory : IDbContextFactory<AuthDbContext>
    {
        public AuthDbContext CreateDbContext() => throw new InvalidOperationException("Database should not be accessed.");
        public Task<AuthDbContext> CreateDbContextAsync(CancellationToken cancellationToken = default) =>
            throw new InvalidOperationException("Database should not be accessed.");
    }
}
